import fs from "node:fs/promises";
import crypto from "node:crypto";
import { buildArtifactLocation, getArtifactDir } from "../shared/artifact-paths.js";
import { formatApprovalSummaryList, formatWorkflowLabel, renderArtifactCoverageLine, renderArtifactDocument, renderWorkflowLinkedSummaryLines } from "../shared/artifact-render.js";

export class TraceArtifactManager {
  constructor({ config, stateStore }) {
    this.config = config;
    this.stateStore = stateStore;
    this.artifactDir = getArtifactDir(config, "agent-traces");
  }

  async exportTraceArtifact({ traceId = "", workflowId = "", title = "", limit = 20 }) {
    const traces = traceId
      ? [await this.stateStore.getTrace(traceId)].filter(Boolean)
      : workflowId
        ? await this.stateStore.listTracesByWorkflow(workflowId, limit)
        : await this.stateStore.listTraces(limit);
    const linkedWorkflow = workflowId ? await this.stateStore.getWorkflowRun(workflowId) : null;
    const linkedWorkflowArtifacts = workflowId ? await this.stateStore.listWorkflowArtifactsByWorkflow(workflowId) : [];
    const workflowBundle = workflowId ? await this.stateStore.getWorkflowBundle(workflowId) : null;

    if (traces.length === 0) {
      throw new Error("No trace record available to export.");
    }

    const createdAt = new Date().toISOString();
    const safeTitle = slugify(title || "trace-log").slice(0, 80) || "trace-log";
    const timestamp = createdAt.replace(/[:]/g, "-").replace(/\..+$/, "");
    const { absolutePath, storedPath } = buildArtifactLocation(this.config, "agent-traces", `${timestamp}-${safeTitle}.md`);

    await fs.mkdir(this.artifactDir, { recursive: true });
    await fs.writeFile(
      absolutePath,
      renderTraceDocument({ traces, title, createdAt, linkedWorkflow, linkedWorkflowArtifacts, workflowBundle }),
      "utf8"
    );

    const record = {
      id: `traceartifact_${crypto.randomUUID()}`,
      createdAt,
      title: title || "trace log",
      path: storedPath,
      traceCount: traces.length,
      traceIds: traces.map((trace) => trace.id),
      workflowId: workflowId || null
    };

    await this.stateStore.saveTraceArtifact(record);
    return record;
  }
}

function renderTraceDocument({ traces, title, createdAt, linkedWorkflow, linkedWorkflowArtifacts, workflowBundle }) {
  return renderArtifactDocument({
    title: title || "trace log",
    metadata: [
      `Generated at: ${createdAt}`,
      `Trace count: ${traces.length}`,
      `Workflow: ${formatWorkflowLabel(linkedWorkflow)}`,
      renderArtifactCoverageLine(linkedWorkflow?.dashboardSummary?.artifactCoverage)
    ],
    sections: [
      {
        title: "Linked Summary",
        lines: renderWorkflowLinkedSummaryLines({
          linkedWorkflow,
          linkedWorkflowArtifacts,
          includeReviewCount: true
        }).concat([
          `- Workflow approval summaries: ${formatApprovalSummaryList(workflowBundle?.approvalRequests || [])}`
        ])
      },
      {
        title: "Traces",
        lines: traces.flatMap((trace) => [
          `### ${trace.id}`,
          `- Kind: ${trace.kind}`,
          `- Created at: ${trace.createdAt}`,
          "",
          "```json",
          JSON.stringify(trace, null, 2),
          "```",
          ""
        ])
      }
    ],
    notes: [
      "This file was generated by the coding-agent trace artifact exporter.",
      "Export a fresh trace artifact after additional model/tool activity if you need a later audit snapshot."
    ]
  });
}

function slugify(value) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9\u4e00-\u9fa5]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
